-- GuideMe V5 schema definition. Use for provisioning a new empty V5 database only; never run against an existing production database.
PRAGMA foreign_keys=ON;
CREATE TABLE Guides(GuideId INTEGER PRIMARY KEY,GuideKey TEXT NOT NULL UNIQUE,GuideName TEXT NOT NULL);
CREATE TABLE GuideApplicationContexts(GuideId INTEGER NOT NULL,ContextId TEXT NOT NULL,Runtime TEXT NOT NULL,PRIMARY KEY(GuideId,ContextId),FOREIGN KEY(GuideId) REFERENCES Guides(GuideId));
CREATE TABLE ApplicationContextMatchers(GuideId INTEGER NOT NULL,ContextId TEXT NOT NULL,MatcherId TEXT NOT NULL,MatcherOrder INTEGER NOT NULL,Kind TEXT NOT NULL,Value TEXT NOT NULL,PRIMARY KEY(GuideId,ContextId,MatcherId),UNIQUE(GuideId,ContextId,MatcherOrder),FOREIGN KEY(GuideId,ContextId) REFERENCES GuideApplicationContexts(GuideId,ContextId));
CREATE TABLE GuideSteps(GuideId INTEGER NOT NULL,StepId TEXT NOT NULL,StepOrder INTEGER NOT NULL,IsEnabled INTEGER NOT NULL CHECK(IsEnabled IN(0,1)),ApplicationContextId TEXT,ContextKind TEXT,ContextValue TEXT,PRIMARY KEY(GuideId,StepId),UNIQUE(GuideId,StepOrder),FOREIGN KEY(GuideId) REFERENCES Guides(GuideId),FOREIGN KEY(GuideId,ApplicationContextId) REFERENCES GuideApplicationContexts(GuideId,ContextId));
CREATE TABLE StepBubbles(GuideId INTEGER NOT NULL,StepId TEXT NOT NULL,Content TEXT NOT NULL,Placement TEXT NOT NULL,PRIMARY KEY(GuideId,StepId),FOREIGN KEY(GuideId,StepId) REFERENCES GuideSteps(GuideId,StepId));
CREATE TABLE GuideElements(GuideId INTEGER NOT NULL,ElementId TEXT NOT NULL,Runtime TEXT,FrameContextJson TEXT,PRIMARY KEY(GuideId,ElementId),FOREIGN KEY(GuideId) REFERENCES Guides(GuideId));
CREATE TABLE ElementLocators(GuideId INTEGER NOT NULL,ElementId TEXT NOT NULL,LocatorId TEXT NOT NULL,Strategy TEXT NOT NULL,Value TEXT NOT NULL,PRIMARY KEY(GuideId,ElementId,LocatorId),FOREIGN KEY(GuideId,ElementId) REFERENCES GuideElements(GuideId,ElementId));
CREATE TABLE ElementAnchorRelations(GuideId INTEGER NOT NULL,ElementId TEXT NOT NULL,AnchorElementId TEXT NOT NULL,Relation TEXT NOT NULL,AnchorOrder INTEGER NOT NULL,RelationId TEXT NOT NULL,PRIMARY KEY(GuideId,ElementId,RelationId),UNIQUE(GuideId,ElementId,AnchorOrder),FOREIGN KEY(GuideId,ElementId) REFERENCES GuideElements(GuideId,ElementId),FOREIGN KEY(GuideId,AnchorElementId) REFERENCES GuideElements(GuideId,ElementId));
CREATE TABLE StepElementUsages(GuideId INTEGER NOT NULL,StepId TEXT NOT NULL,UsageId TEXT NOT NULL,ElementId TEXT NOT NULL,Purpose TEXT NOT NULL,PRIMARY KEY(GuideId,StepId,UsageId),FOREIGN KEY(GuideId,StepId) REFERENCES GuideSteps(GuideId,StepId),FOREIGN KEY(GuideId,ElementId) REFERENCES GuideElements(GuideId,ElementId));
CREATE TABLE StepCaptures(GuideId INTEGER NOT NULL,StepId TEXT NOT NULL,CaptureId TEXT NOT NULL,TargetUsageId TEXT NOT NULL,Property TEXT NOT NULL,Pattern TEXT,Timing TEXT,PRIMARY KEY(GuideId,StepId,CaptureId),FOREIGN KEY(GuideId,StepId,TargetUsageId) REFERENCES StepElementUsages(GuideId,StepId,UsageId));
CREATE TABLE StepAdvancePolicies(GuideId INTEGER NOT NULL,StepId TEXT NOT NULL,PolicyKind TEXT NOT NULL CHECK(PolicyKind IN ('AutomaticOnValidation','Manual')),PRIMARY KEY(GuideId,StepId),FOREIGN KEY(GuideId,StepId) REFERENCES GuideSteps(GuideId,StepId) ON DELETE CASCADE);
CREATE TABLE StepObservedSignals(GuideId INTEGER NOT NULL,StepId TEXT NOT NULL,SignalId TEXT NOT NULL,SignalOrder INTEGER NOT NULL,SignalRole TEXT NOT NULL CHECK(SignalRole IN ('PrimaryValidation','AdditionalCompletionCondition')),Kind TEXT NOT NULL,TargetUsageId TEXT,ExpectedValue TEXT,OptionsJson TEXT,PRIMARY KEY(GuideId,StepId,SignalId),UNIQUE(GuideId,StepId,SignalOrder),FOREIGN KEY(GuideId,StepId) REFERENCES GuideSteps(GuideId,StepId) ON DELETE CASCADE,FOREIGN KEY(GuideId,StepId,TargetUsageId) REFERENCES StepElementUsages(GuideId,StepId,UsageId));
